<?php require_once __DIR__.'/includes/bootstrap.php';require_once __DIR__.'/config/db.php';$error='';$sent=false;if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf($_POST['csrf_token']??null)||!filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL)||trim($_POST['message']??'')==='')$error='Please provide a valid email and message.';else try{$q=db()->prepare('INSERT INTO contact_messages(name,email,subject,message) VALUES(?,?,?,?)');$q->execute([trim($_POST['name']??''),$_POST['email'],trim($_POST['subject']??''),trim($_POST['message'])]);$sent=true;}catch(Throwable $e){$error='Contact form is temporarily unavailable.';}}$pageTitle='Contact us';require __DIR__.'/includes/header.php';require __DIR__.'/includes/navbar.php';?><main class="container py-5" style="max-width:700px"><h1 class="h2">Contact us</h1><?php if($sent):?><div class="alert alert-success">Thanks—we received your message.</div><?php elseif($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input class="form-control mb-3" name="name" placeholder="Name"><input class="form-control mb-3" type="email" name="email" placeholder="Email" required><input class="form-control mb-3" name="subject" placeholder="Subject"><textarea class="form-control mb-3" name="message" rows="5" required placeholder="Message"></textarea><button class="btn btn-brand">Send message</button></form></main><?php require __DIR__.'/includes/footer.php';?>
